'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var dcopy = require( '@stdlib/blas/base/dcopy' );
var Float64Array = require( '@stdlib/array/float64' );
var format = require( '@stdlib/string/format' );
var rffti = require( '@stdlib/fft/base/fftpack/rffti' );
var pkg = require( './../package.json' ).name;
var rfftf = require( './../lib' );


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} iter - number of iterations
* @param {PositiveInteger} N - sequence length to transform
* @returns {Function} benchmark function
*/
function createBenchmark( iter, N ) {
	var workspace;
	var tmp;
	var x;
	var i;

	x = [];
	for ( i = 0; i < iter; i++ ) {
		tmp = uniform( N, -10.0, 10.0, {
			'dtype': 'float64'
		});
		x.push( tmp );
	}

	workspace = new Float64Array( ( 2*N ) + 34 );
	rffti( N, workspace, 1, 0 );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var xc;
		var c;
		var i;

		xc = x.slice();
		for ( i = 0; i < iter; i++ ) {
			xc[ i ] = dcopy( N, x[ i ], 1, new Float64Array( N ), 1 );
		}
		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			c = xc[ i%iter ];
			rfftf( N, c, 1, 0, workspace, 1, 0 );
			if ( isnan( c[ i%N ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( c[ i%N ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var lengths;
	var opts;
	var iter;
	var N;
	var f;
	var i;

	iter = 1e6;
	lengths = [
		8,
		16,
		32,
		64,
		128,
		256
	];

	for ( i = 0; i < lengths.length; i++ ) {
		N = lengths[ i ];
		f = createBenchmark( iter, N );
		opts = {
			'iterations': iter
		};
		bench( format( '%s:N=%d', pkg, N ), opts, f );
		iter = floor( pow( iter, 3.0/4.0 ) );
	}
}

main();
